import {displayNetworkFee} from './network-fees.mjs';
import {mountDashboard,icon} from './dashboard.mjs';
import {currencyFields,CURRENCIES,historyHTML,renderHistory} from './transfer-ui.mjs';
import {createFundingService} from './funding-service.mjs';
import {RECEIVING_ROUTES} from './receiving-routes.mjs';
import {fromUnits,toUnits,NETWORKS,validateAddress,validateMemo} from './funding-catalog.mjs';
export function withdrawalHTML(){return '<div class="deposit-page"><div class="deposit-page-heading"><span class="deposit-heading-icon">'+icon('withdraw')+'</span><div><h1>Withdraw Crypto</h1><p>Request a transfer to your external wallet</p></div></div><div class="deposit-columns"><section class="deposit-panel"><h2>'+icon('wallet')+' New Withdrawal</h2><div class="payment-important"><strong>Manually processed</strong><p>Your requested amount is reserved from your available balance. An administrator reviews and sends the funds, then records the payout transaction here.</p></div><div class="deposit-current-balance"><span>Available Balance</span><strong id="withdraw-balance">Sign in to view balance</strong></div><form id="withdraw-form"><div id="withdraw-currency-fields">'+currencyFields('withdraw','BTC','bitcoin',RECEIVING_ROUTES)+'</div><div class="transfer-field"><label for="withdraw-address">Receiving wallet address</label><input id="withdraw-address" autocomplete="off" maxlength="180" required placeholder="Enter your destination address"></div><div class="transfer-field" id="withdraw-memo-field" hidden><label for="withdraw-memo">Memo / destination tag (if required)</label><input id="withdraw-memo" maxlength="128" autocomplete="off"></div><div class="transfer-field"><label for="withdraw-amount">Withdrawal amount</label><input id="withdraw-amount" inputmode="decimal" placeholder="0.00" required></div><dl class="withdraw-summary"><div><dt>Network fee</dt><dd>Recorded after manual payment; not deducted from your site balance</dd></div><div><dt>Requested payout</dt><dd id="withdraw-payout">—</dd></div><div><dt>Reserved balance</dt><dd id="withdraw-reserved">—</dd></div></dl><p id="withdraw-network-estimate" class="transfer-caption network-fee-info"></p><label class="funding-consent"><input id="withdraw-consent" type="checkbox" required> I checked the address and network. I understand this request will be reviewed and sent manually.</label><button type="submit" class="deposit-continue">Request Withdrawal</button><p id="withdraw-feedback" class="transfer-caption" role="status"></p></form></section>'+historyHTML('withdraw')+'</div></div>';}
export function mountWithdrawal(root,options={}){mountDashboard(root,{...options,view:'withdraw',mainHTML:withdrawalHTML()});let asset='BTC',network='bitcoin',service=null,data={routes:RECEIVING_ROUTES,balances:[],history:[]},id=crypto.randomUUID(),busy=false;const feedback=root.querySelector('#withdraw-feedback'),submit=root.querySelector('#withdraw-form button[type="submit"]');submit.disabled=true;
 function balances(){const b=data.balances.find(b=>b.asset===asset);root.querySelector('#withdraw-balance').textContent=service?(b?.available||'0')+' '+asset:'Sign in to view balance';root.querySelector('#withdraw-reserved').textContent=service?(b?.reserved||'0')+' '+asset:'—';submit.disabled=!service||!data.routes.find(r=>r.asset===asset&&r.network===network)?.enabled;root.querySelector('#withdraw-memo-field').hidden=!NETWORKS[network]?.memoLabel;}
 async function refresh(){data=await service.load();balances();renderHistory(root.querySelector('#funding-history'),data.history.filter(r=>r.kind==='withdrawal'||r.kind==='simulation'),{cancel:async(row,button)=>{button.disabled=true;try{await service.cancel(row.id);await refresh();feedback.textContent='Request cancelled. The reserved amount is available again.';}catch(e){feedback.textContent=e.message;button.disabled=false;}}});}
 function fields(){root.querySelector('#withdraw-currency-fields').innerHTML=currencyFields('withdraw',asset,network,data.routes);root.querySelector('#withdraw-currency').onchange=e=>{asset=e.target.value;network=CURRENCIES[asset].networks[0];root.querySelector('#withdraw-address').value='';root.querySelector('#withdraw-memo').value='';root.querySelector('#withdraw-consent').checked=false;fields();};root.querySelector('#withdraw-network').onchange=e=>{network=e.target.value;root.querySelector('#withdraw-address').value='';root.querySelector('#withdraw-memo').value='';root.querySelector('#withdraw-consent').checked=false;fields();};balances();displayNetworkFee(root.querySelector('#withdraw-network-estimate'),asset,network);}
 const historyHeading=root.querySelector('.deposit-history h2'),refreshButton=document.createElement('button');refreshButton.type='button';refreshButton.className='transfer-back';refreshButton.textContent='Refresh status';refreshButton.onclick=()=>refresh().catch(e=>feedback.textContent=e.message);historyHeading.after(refreshButton);
 const marker=root.querySelector('#withdraw-form');const onFocus=()=>{if(service&&!busy&&marker.isConnected)refresh().catch(e=>feedback.textContent=e.message);};window.addEventListener('focus',onFocus);const observer=new MutationObserver(()=>{if(!marker.isConnected){window.removeEventListener('focus',onFocus);observer.disconnect();}});observer.observe(root,{subtree:true,childList:true});
 fields();root.querySelector('#withdraw-amount').oninput=e=>{try{root.querySelector('#withdraw-payout').textContent=fromUnits(toUnits(e.target.value,asset),asset)+' '+asset;}catch{root.querySelector('#withdraw-payout').textContent='—';}};
 root.querySelector('#withdraw-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;submit.disabled=true;feedback.textContent='';try{if(!service)throw Error('Sign in to request a withdrawal.');if(!root.querySelector('#withdraw-consent').checked)throw Error('Confirm the receiving address and network.');const amount=fromUnits(toUnits(root.querySelector('#withdraw-amount').value,asset),asset),address=validateAddress(network,root.querySelector('#withdraw-address').value),memo=validateMemo(network,root.querySelector('#withdraw-memo').value);await service.create('withdrawal',asset,network,amount,id,{address,memo});id=crypto.randomUUID();await refresh();feedback.textContent='Withdrawal requested. '+amount+' '+asset+' is reserved. Awaiting manual review and payment.';root.querySelector('#withdraw-consent').checked=false;}catch(e){feedback.textContent=e.message;}finally{busy=false;balances();}};
 if(!options.preview)Promise.resolve(options.getAccounts?.()).then(async accounts=>{if(!accounts)return;service=createFundingService(accounts);await refresh();fields();}).catch(e=>feedback.textContent=e.message);window.scrollTo(0,0);
}
